// GÉNÉRÉ depuis docs/template/03 Accueil v2.dc.html, section MOB, cadre 390 px.
// Ne pas modifier à la main : relancer `node tools/generate-screens.mjs`.
//
// Les styles en ligne sont ceux de la maquette, à l'identique. Le conteneur
// extérieur, lui, est fluide : la maquette le fige à 390 px, ce qui ne
// serait pas responsive.
import { Fragment } from 'react';
import Link from 'next/link';
import type { A10Data } from './data';

export function A10Mobile(props: A10Data) {
  const { categorie, categorieLabel, categorieOptions, couvertureOccupee, couvertureUrl, creerEncre, creerFond, creerPret, invitees, invitesBarre, invitesResteCourt, invitesTexte, nomMax, nomValue, onCategorie, onCouverture, onCreer, onFermer, onInviter, onNomChange, onVisibilite, visibility } = props;

  return (
    <>
      <main style={{ display: "contents" }}>
<div style={{ padding: "calc(env(safe-area-inset-top, 0px) + 12px) 12px 10px", display: "flex", alignItems: "center", gap: "8px", background: "#fff", borderBottom: "1px solid #E6EBE9", flexShrink: "0" }}><button type="button" onClick={onFermer} aria-label="Fermer" style={{ border: "none", fontFamily: "inherit", color: "inherit", cursor: "pointer", padding: 0, width: "40px", height: "40px", borderRadius: "999px", background: "#F2F5F4", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: "0" }}><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#16211D" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18M6 6l12 12" /></svg></button><h1 style={{ margin: "0", fontSize: "15.5px", fontWeight: "700", flex: "1" }}>Nouveau réseau d'intérêt</h1></div><div style={{ flexGrow: "1", overflow: "visible", padding: "12px 16px", display: "flex", flexDirection: "column", gap: "12px" }}><label style={{ height: "84px", borderRadius: "16px", border: "1.5px dashed #CBD5D1", background: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "12.5px", fontWeight: "700", color: "#5D6B66", flexShrink: "0", cursor: couvertureOccupee ? "default" : "pointer", backgroundImage: couvertureUrl === null ? "none" : `url("${couvertureUrl}")`, backgroundSize: "cover", backgroundPosition: "center", overflow: "hidden" }} data-creation-couverture=""><input type="file" accept="image/jpeg,image/png,image/webp" hidden disabled={couvertureOccupee} onChange={onCouverture} data-creation-couverture-fichier="" />{couvertureOccupee ? "Envoi de la couverture…" : couvertureUrl === null ? "Ajouter une couverture" : (<span style={{ padding: "6px 12px", borderRadius: "12px", background: "rgba(255,255,255,.92)", color: "#16211D" }}>Changer la couverture</span>)}</label><input style={{ height: "48px", borderRadius: "14px", border: "1.5px solid #16785E", background: "#fff", padding: "0 14px", display: "flex", alignItems: "center", fontSize: "14.5px", fontWeight: "600", flexShrink: "0" }} placeholder="Entrepreneurs africains à Lyon" type="text" name="name" autoComplete="off" aria-label="Nom du réseau" maxLength={nomMax} value={nomValue} onChange={onNomChange} /><div style={{ display: "flex", gap: "6px", flexShrink: "0" }}><span style={{ padding: "7px 12px", borderRadius: "999px", backgroundColor: "#fff", border: "1px solid #E6EBE9", fontSize: "12px", fontWeight: "600", position: "relative" }}>{categorieLabel} ▾<select value={categorie} onChange={onCategorie} aria-label="Catégorie du réseau" style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", opacity: 0, cursor: "pointer", font: "inherit", border: "none", appearance: "none" }}>{(categorieOptions ?? []).map((c) => (<option key={c.value} value={c.value}>{c.label}</option>))}</select></span></div><div style={{ display: "flex", gap: "4px", background: "#EEF2F0", borderRadius: "12px", padding: "4px", flexShrink: "0" }}>{(visibility ?? []).map((v, vIndex) => (
<Fragment key={vIndex}>{v.on ? (<><button type="button" onClick={() => onVisibilite(vIndex)} aria-pressed={v.on} style={{ flex: "1", textAlign: "center", padding: "8px 4px", borderRadius: "9px", fontSize: "12.5px", fontWeight: "700", whiteSpace: "nowrap", background: "#fff", fontFamily: "inherit", color: "inherit", cursor: "pointer", border: "none" }}>{v.t}</button></>) : null}{!v.on ? (<><button type="button" onClick={() => onVisibilite(vIndex)} aria-pressed={v.on} style={{ flex: "1", textAlign: "center", padding: "8px 4px", borderRadius: "9px", fontSize: "12.5px", fontWeight: "700", whiteSpace: "nowrap", color: "#5D6B66", fontFamily: "inherit", cursor: "pointer", border: "none", backgroundColor: "transparent" }}>{v.t}</button></>) : null}</Fragment>
))}</div><div style={{ background: "#fff", border: "1px solid #E6EBE9", borderRadius: "20px", padding: "14px", flexShrink: "0" }}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><span style={{ fontSize: "14.5px", fontWeight: "700" }}>Invitez au moins 5 membres</span><span style={{ background: "#FBE3D4", color: "#B4581F", fontSize: "12px", fontWeight: "700", padding: "4px 10px", borderRadius: "999px" }}>{invitesTexte}</span></div><div style={{ height: "6px", borderRadius: "999px", background: "#EEF2F0", marginTop: "10px", overflow: "hidden" }}><div style={{ width: invitesBarre, height: "100%", background: "#E0733A" }}></div></div><div style={{ display: "flex", flexDirection: "column", gap: "10px", marginTop: "12px" }}>{(invitees ?? []).map((i, iIndex) => (
<Fragment key={iIndex}><div style={{ display: "flex", alignItems: "center", gap: "10px", flexShrink: "0" }}>{i.profil ? (<Link href={i.profil} data-avatar-profil="" aria-label={`Voir le profil de ${i.name}`} style={{ display: "contents", color: "inherit", textDecoration: "none" }}><span style={{ width: "36px", height: "36px", borderRadius: "999px", background: i.bg, color: "#fff", fontSize: "12px", fontWeight: "700", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: "0" }}>{i.i}</span></Link>) : (<span style={{ width: "36px", height: "36px", borderRadius: "999px", background: i.bg, color: "#fff", fontSize: "12px", fontWeight: "700", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: "0" }}>{i.i}</span>)}<span style={{ flex: "1", minWidth: "0" }}><span style={{ display: "flex", alignItems: "center", gap: "5px", fontSize: "13.5px", fontWeight: "700" }}>{i.profil ? (<Link href={i.profil} data-nom-profil="" style={{ color: "inherit", textDecoration: "none" }}>{i.name}</Link>) : i.name}<svg width="12" height="12" viewBox="0 0 24 24" fill="#16785E"><circle cx="12" cy="12" r="10" /><path d="m8 12 3 3 5-6" stroke="#fff" strokeWidth="2.2" fill="none" /></svg></span><span style={{ display: "block", fontSize: "11.5px", color: "#8A958F" }}>{i.sub}</span></span><button type="button" onClick={() => onInviter(i.handle)} aria-pressed={i.invited} style={{ height: "32px", padding: "0 12px", borderRadius: "999px", fontSize: "12px", fontWeight: "700", display: "flex", alignItems: "center", background: i.btnBg, color: i.btnFg, fontFamily: "inherit", cursor: "pointer", border: "none" }}>{i.btn}</button></div></Fragment>
))}</div></div></div><div style={{ flexShrink: "0", background: "#fff", borderTop: "1px solid #E6EBE9", padding: "12px 16px 28px", display: "flex", flexDirection: "column", gap: "6px" }}><button type="button" onClick={onCreer} disabled={!creerPret} style={{ height: "50px", borderRadius: "14px", backgroundColor: creerFond, color: creerEncre, border: "none", font: "inherit", fontSize: "14.5px", fontWeight: "700", flexShrink: "0", cursor: creerPret ? "pointer" : "default" }}>Créer le réseau</button><div style={{ fontSize: "11.5px", color: "#8A958F", textAlign: "center" }}>{invitesResteCourt}</div></div>
      </main>
    </>
  );
}
